-- Story 4.7.1 / AD-21: one immutable invite token per user, opened as
-- `/i/:token`. "userId" is the primary key, so a second link cannot exist, the
-- token is never rewritten and a deleted account drops the link with
-- ON DELETE CASCADE. The token is a CUID2 generated by the server and never
-- derived from the nick (A-26); registration with a valid token creates the
-- "Friendship" in the same transaction unless a "Block" exists (AD-21).

-- CreateTable
CREATE TABLE "InviteLink" (
    "userId" TEXT NOT NULL,
    "token" TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "InviteLink_pkey" PRIMARY KEY ("userId")
);

-- CreateIndex
CREATE UNIQUE INDEX "InviteLink_token_key" ON "InviteLink"("token");

-- AddForeignKey
ALTER TABLE "InviteLink" ADD CONSTRAINT "InviteLink_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
